// Authored by Kimi Code (AI coding agent) — task CHRON-025.
//! Utility-AI data-construction baseline for CHRON-025 (the `bench_utility_ai`
//! enumeration half, Master Spec §75): full `candidate_actions` enumeration
//! and `trace_for` construction for the full candidate set at 100 and 1,000
//! persons over one generated 128×128 map with the deterministic
//! `ActivitySites::place_defaults` site set (six sites, the lower end of the
//! spec's 6–20 range). Persons are plain `(LocalCoord, Needs)` pairs
//! generated by a deterministic stride pattern — `sim-ai` does not depend on
//! `sim-core`. Median of ten post-warm-up samples; correctness assertions
//! remain enabled. The scoring/selection half is measured in CHRON-026. RSS
//! is sampled best-effort via `ps` (KiB units on macOS/Linux).

use std::hint::black_box;
use std::process::Command;
use std::time::Instant;

use palimpsest_sim_ai::{
    ActionKind, CandidateContext, DecisionTrace, NeedValue, Needs, candidate_actions, trace_for,
};
use palimpsest_sim_world::{
    ActivitySites, LocalCoord, PathConfig, WorldGenConfig, WorldMap, WorldSeed,
};

/// The two scales this baseline reports.
const SCALES: [usize; 2] = [100, 1_000];
/// Hunger pattern multiplier (deterministic, spreads raw values over the
/// full `NeedValue` range).
const HUNGER_STRIDE: i64 = 7_919;
/// Fatigue pattern multiplier (a different stride decorrelates the drives).
const FATIGUE_STRIDE: i64 = 10_873;
/// Raw needs modulus: the full `[0, NEED_MAX]` range inclusive.
const NEED_MODULUS: i64 = 100_001;

fn main() {
    let mut arguments = std::env::args().skip(1);
    let sample_count = arguments.next().map_or(10, |value| {
        value.parse::<usize>().expect("sample count must be usize")
    });
    let warmup_count = arguments.next().map_or(2, |value| {
        value.parse::<usize>().expect("warmup count must be usize")
    });
    assert!(sample_count > 0, "sample count must be positive");

    let map = WorldMap::generate(WorldSeed::new(0), WorldGenConfig::default());
    let sites = ActivitySites::place_defaults(&map);
    assert_eq!(
        sites.len(),
        6,
        "place_defaults spreads six sites (two per kind) on generated terrain"
    );
    let site_count = sites.len();

    for scale in SCALES {
        let persons = generate_persons(&map, scale);
        assert_eq!(persons.len(), scale);

        for _ in 0..warmup_count {
            black_box(run_enumeration(&persons, &sites, &map));
            black_box(run_traces(&persons, &sites, &map));
        }

        let mut enumeration_samples = Vec::with_capacity(sample_count);
        let mut trace_samples = Vec::with_capacity(sample_count);
        let mut enumeration_checksum = None;
        let mut trace_checksum = None;
        let mut candidates_total = 0_usize;
        let mut traces_total = 0_usize;
        for _ in 0..sample_count {
            let started = Instant::now();
            let (total, checksum) = run_enumeration(&persons, &sites, &map);
            enumeration_samples.push(started.elapsed());
            match enumeration_checksum {
                None => {
                    enumeration_checksum = Some(checksum);
                    candidates_total = total;
                }
                Some(reference) => assert_eq!(
                    checksum, reference,
                    "candidate enumeration must be deterministic across samples"
                ),
            }

            let started = Instant::now();
            let (total, checksum) = run_traces(&persons, &sites, &map);
            trace_samples.push(started.elapsed());
            match trace_checksum {
                None => {
                    trace_checksum = Some(checksum);
                    traces_total = total;
                }
                Some(reference) => assert_eq!(
                    checksum, reference,
                    "trace construction must be deterministic across samples"
                ),
            }
        }

        let rss_before = current_rss_bytes();
        let retained = retain_all_traces(&persons, &sites, &map);
        black_box(&retained);
        let rss_after = current_rss_bytes();
        let rss_delta = rss_after
            .zip(rss_before)
            .map(|(after, before)| after.saturating_sub(before));

        enumeration_samples.sort_unstable();
        trace_samples.sort_unstable();
        let enumeration_median = enumeration_samples[sample_count / 2];
        let trace_median = trace_samples[sample_count / 2];
        let candidates_f64 =
            f64::from(u32::try_from(candidates_total).expect("candidate count fits u32"));
        let traces_f64 = f64::from(u32::try_from(traces_total).expect("trace count fits u32"));
        println!(
            "{{\"persons\":{scale},\"sites\":{site_count},\"samples\":{sample_count},\
             \"candidates_total\":{candidates_total},\
             \"enumeration_min_ns\":{},\"enumeration_median_ns\":{},\
             \"enumeration_max_ns\":{},\"candidates_per_second\":{:.3},\
             \"traces_total\":{traces_total},\
             \"trace_min_ns\":{},\"trace_median_ns\":{},\"trace_max_ns\":{},\
             \"full_traces_per_second\":{:.3},\"rss_delta_bytes\":{},\
             \"enumeration_checksum\":{},\"trace_checksum\":{}}}",
            enumeration_samples
                .first()
                .expect("samples exist")
                .as_nanos(),
            enumeration_median.as_nanos(),
            enumeration_samples[sample_count - 1].as_nanos(),
            candidates_f64 / enumeration_median.as_secs_f64(),
            trace_samples.first().expect("samples exist").as_nanos(),
            trace_median.as_nanos(),
            trace_samples[sample_count - 1].as_nanos(),
            traces_f64 / trace_median.as_secs_f64(),
            json_u64(rss_delta),
            enumeration_checksum.expect("at least one sample ran"),
            trace_checksum.expect("at least one sample ran"),
        );
    }
}

/// Generates `count` deterministic persons: locations strided evenly over the
/// map's walkable cells, hunger/fatigue patterned over the full need range.
fn generate_persons(map: &WorldMap, count: usize) -> Vec<(LocalCoord, Needs)> {
    let walkable: Vec<LocalCoord> = map
        .local()
        .coords()
        .filter(|coord| {
            map.local()
                .get(coord.x(), coord.y())
                .is_some_and(|kind| kind.is_walkable())
        })
        .collect();
    assert!(
        !walkable.is_empty(),
        "generated map must offer walkable cells"
    );
    let stride = (walkable.len() / count).max(1);
    (0..count)
        .map(|index| {
            let location = walkable[(index * stride) % walkable.len()];
            let patterned = i64::try_from(index).expect("person index fits i64");
            let hunger = NeedValue::from_raw((patterned * HUNGER_STRIDE) % NEED_MODULUS)
                .expect("patterned hunger in range");
            let fatigue = NeedValue::from_raw((patterned * FATIGUE_STRIDE) % NEED_MODULUS)
                .expect("patterned fatigue in range");
            (location, Needs::new(hunger, fatigue))
        })
        .collect()
}

/// Enumerates the full candidate set for every person; returns the total
/// candidate count and a determinism checksum.
fn run_enumeration(
    persons: &[(LocalCoord, Needs)],
    sites: &ActivitySites,
    map: &WorldMap,
) -> (usize, u64) {
    let mut total = 0_usize;
    let mut checksum = 0_u64;
    for &(location, needs) in persons {
        let context = CandidateContext::new(location, needs, sites, map, PathConfig::default());
        let candidates = candidate_actions(black_box(&context));
        // Correctness: the Idle baseline is always last and untargeted, and
        // enumeration keys are the contiguous 0-based positions.
        let last = candidates.last().expect("idle baseline is always present");
        assert_eq!(last.kind(), ActionKind::Idle);
        assert_eq!(last.target(), None);
        for (position, candidate) in candidates.iter().enumerate() {
            assert_eq!(
                candidate.order(),
                u64::try_from(position).expect("position fits u64")
            );
            let kind_key = match candidate.kind() {
                ActionKind::Move => 0_u64,
                ActionKind::Eat => 1,
                ActionKind::Sleep => 2,
                ActionKind::Work => 3,
                ActionKind::Idle => 4,
            };
            checksum = checksum.wrapping_add(kind_key).wrapping_add(
                candidate.target().map_or(0, |target| {
                    u64::try_from(target.index()).expect("index fits u64")
                }),
            );
        }
        total += candidates.len();
    }
    (total, checksum)
}

/// Builds the single-candidate decision trace for every enumerated candidate
/// of every person; returns the total trace count and a determinism
/// checksum over the recorded factor inputs.
fn run_traces(
    persons: &[(LocalCoord, Needs)],
    sites: &ActivitySites,
    map: &WorldMap,
) -> (usize, u64) {
    let mut total = 0_usize;
    let mut checksum = 0_u64;
    for &(location, needs) in persons {
        let context = CandidateContext::new(location, needs, sites, map, PathConfig::default());
        for candidate in candidate_actions(&context) {
            let trace = trace_for(black_box(&candidate), black_box(&context));
            // Correctness: CHRON-025 leaves every scoring field unset and
            // records the uniform five-factor input set.
            assert_eq!(trace.selected(), None);
            assert_eq!(trace.tie_break(), None);
            assert_eq!(trace.candidates().len(), 1);
            let candidate_trace = &trace.candidates()[0];
            assert_eq!(candidate_trace.total(), None);
            assert_eq!(candidate_trace.factors().len(), 5);
            for evaluation in candidate_trace.factors() {
                assert_eq!(evaluation.contribution(), None);
                checksum = checksum.wrapping_add(evaluation.input().input().cast_unsigned());
            }
            total += 1;
        }
    }
    (total, checksum)
}

/// Builds and retains every per-candidate trace for the RSS delta sample.
fn retain_all_traces(
    persons: &[(LocalCoord, Needs)],
    sites: &ActivitySites,
    map: &WorldMap,
) -> Vec<DecisionTrace> {
    let mut retained = Vec::new();
    for &(location, needs) in persons {
        let context = CandidateContext::new(location, needs, sites, map, PathConfig::default());
        for candidate in candidate_actions(&context) {
            retained.push(trace_for(&candidate, &context));
        }
    }
    retained
}

fn current_rss_bytes() -> Option<u64> {
    let pid = std::process::id().to_string();
    let output = Command::new("ps")
        .args(["-o", "rss=", "-p", &pid])
        .output()
        .ok()?;
    let text = String::from_utf8(output.stdout).ok()?;
    text.trim().parse::<u64>().ok()?.checked_mul(1024)
}

fn json_u64(value: Option<u64>) -> String {
    value.map_or_else(|| "null".to_owned(), |number| number.to_string())
}
